import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Среда выполнения и загрузка скриптов","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/lua/environment.md","filePath":"ru/development/lua/environment.md","lastUpdated":1791683719000}`),a={name:`ru/development/lua/environment.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="среда-выполнения-и-загрузка-скриптов" tabindex="-1">Среда выполнения и загрузка скриптов <a class="header-anchor" href="#среда-выполнения-и-загрузка-скриптов" aria-label="Permalink to “Среда выполнения и загрузка скриптов”">​</a></h1><h2 id="среда-lua" tabindex="-1">Среда Lua <a class="header-anchor" href="#среда-lua" aria-label="Permalink to “Среда Lua”">​</a></h2><p>Сейчас используется GopherLua, который поддерживает синтаксис Lua 5.1, оператор <code>goto</code> из Lua 5.2 и собственный <a href="https://github.com/yuin/gopher-lua#lua-api" target="_blank" rel="noreferrer"><code>channel</code></a>.</p><p>Xray загружает скрипты Lua согласно файлу конфигурации. Положение настройки определяет назначение скрипта и доступные Hook. Hook каждой точки входа и соглашения об их вызове описаны в <a href="./#hook">справочнике Hook</a>.</p><h2 id="загрузка-модулеи" tabindex="-1">Загрузка модулей <a class="header-anchor" href="#загрузка-модулеи" aria-label="Permalink to “Загрузка модулей”">​</a></h2><p>Модули API организованы по назначению и загружаются через <code>require</code>:</p><div class="language-lua line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> geodata</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.geodata&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span>
<span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.log&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Список модулей приведён в разделе <a href="./#api-модулеи">API модулей</a>, а использование функций — в соответствующих справочниках API.</p><p>Когда выполняется инициализация верхнего уровня, включая загрузку модулей Lua и создание объектов, описано в разделе <a href="./guide/lifecycle.html">Экземпляры и жизненный цикл</a>.</p><h2 id="пути-к-фаилам-скриптов" tabindex="-1">Пути к файлам скриптов <a class="header-anchor" href="#пути-к-фаилам-скриптов" aria-label="Permalink to “Пути к файлам скриптов”">​</a></h2><p>Поле <code>script</code> в конфигурации задаёт путь к файлу скрипта Lua. Пустая строка или отсутствие поля отключает скрипт; абсолютный путь указывает файл напрямую.</p><p>Относительные пути проверяются в следующем порядке. Если путь не существует, поиск продолжается; если он существует, но не является обычным файлом, сразу возникает ошибка:</p><ol><li>Каталог, указанный переменной окружения <code>XRAY_LOCATION_CONFDIR</code>;</li><li>Каталог, указанный переменной окружения <code>XRAY_LOCATION_CONFIG</code>;</li><li>Текущий рабочий каталог процесса Xray;</li><li>Каталог исполняемого файла Xray.</li></ol><p>Настройка этих каталогов описана в разделе <a href="./../../config/env.html">Переменные окружения</a>. Относительные пути не отсчитываются автоматически от каталога файла конфигурации.</p><p>Например, если путь скрипта задан как <code>routing.lua</code>, Xray ищет файл в указанном выше порядке. Абсолютный путь Windows можно записать как <code>C:/Xray/routing.lua</code>; при использовании обратной косой черты экранируйте её согласно требованиям формата конфигурации.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};